-- AI/ML pathway ("Cipher Division") Act 24 -- "The Transformer" content.
-- Opens Arc V ("Transformers & Generative AI", Acts 24-27). 1 campaign,
-- 2 operations, 12 missions (11 lessons + boss), following the same
-- campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other Act. Builds self-attention
-- from first principles on a single running example: Echo''s recurring
-- question, "WHERE IS THE ARCHITECT?" World row (world-ai-the-transformer)
-- already exists and is not touched here.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-the-transformer', 'world-ai-the-transformer', 'the-transformer', '24A - The Transformer', 'Self-attention from first principles -- queries, keys, values, attention scores, softmax, multi-head attention, positional information, feed-forward layers and residual connections -- built by hand on Echo''s own recurring question.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-the-transformer-1', 'campaign-ai-the-transformer', 'q-k-and-v', 'Q, K and V', 'Why self-attention, and the three vectors -- query, key and value -- every word gets before any attention score exists.', 1),
  ('operation-ai-the-transformer-2', 'campaign-ai-the-transformer', 'the-full-block', 'The Full Block', 'Softmax, multiple heads, position, feed-forward layers and residual connections, assembled into one complete Transformer block.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-the-transformer-01', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-1', 'why-transformers', 'Why Transformers?', 'Every technique this Arc built got bolted onto older architectures one piece at a time. Elena wants to build the real thing from scratch, starting from Echo''s own recurring question.', 'beginner', ARRAY['maya','elena'], null, null, '{"type":"simulation","simulationId":"why-transformers-sim"}'::jsonb, '{"xp":450,"credits":115}'::jsonb, false, 1),
  ('mission-ai-the-transformer-02', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-1', 'self-attention', 'Self-Attention', 'Self-attention lets every word in a sequence rebuild its own representation by looking at every other word around it, all at once.', 'beginner', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-the-transformer-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"self-attention-sim"}'::jsonb, '{"xp":460,"credits":115}'::jsonb, false, 2),
  ('mission-ai-the-transformer-03', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-1', 'queries', 'Queries', 'The query is the first of three vectors every word gets: what this word is looking for in the rest of the sequence.', 'beginner', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-the-transformer-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"queries-sim"}'::jsonb, '{"xp":460,"credits":120}'::jsonb, false, 3),
  ('mission-ai-the-transformer-04', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-1', 'keys', 'Keys', 'The key is what a word offers up to be matched against every other word''s search.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-the-transformer-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"keys-sim"}'::jsonb, '{"xp":470,"credits":120}'::jsonb, false, 4),
  ('mission-ai-the-transformer-05', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-1', 'values', 'Values', 'The value is the actual content a word contributes once it has been selected by attention.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-the-transformer-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"values-sim"}'::jsonb, '{"xp":470,"credits":120}'::jsonb, false, 5),
  ('mission-ai-the-transformer-06', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-1', 'attention-scores', 'Attention Scores', 'Dot products between queries and keys turn raw vectors into a first real measure of relevance.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-the-transformer-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"attention-scores-sim"}'::jsonb, '{"xp":480,"credits":125}'::jsonb, false, 6),
  ('mission-ai-the-transformer-07', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-2', 'softmax', 'Softmax', 'Softmax turns raw attention scores into a proper distribution of weights that sum to one.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-the-transformer-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"softmax-sim"}'::jsonb, '{"xp":480,"credits":125}'::jsonb, false, 7),
  ('mission-ai-the-transformer-08', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-2', 'multi-head-attention', 'Multi-Head Attention', 'Multiple attention heads run in parallel, each free to learn a different kind of relationship between words.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-the-transformer-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"multi-head-attention-sim"}'::jsonb, '{"xp":490,"credits":125}'::jsonb, false, 8),
  ('mission-ai-the-transformer-09', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-2', 'positional-information', 'Positional Information', 'Self-attention cannot tell word order apart on its own. Positional encoding gives it back.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-the-transformer-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"positional-information-sim"}'::jsonb, '{"xp":490,"credits":130}'::jsonb, false, 9),
  ('mission-ai-the-transformer-10', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-2', 'feed-forward-layers', 'Feed-Forward Layers', 'After attention mixes context between words, a feed-forward layer reshapes each word''s own representation.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-the-transformer-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"feed-forward-sim"}'::jsonb, '{"xp":500,"credits":130}'::jsonb, false, 10),
  ('mission-ai-the-transformer-11', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-2', 'residual-connections', 'Residual Connections', 'Residual connections add each sublayer''s input back to its output, keeping deep Transformer stacks trainable.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-the-transformer-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"residual-connections-sim"}'::jsonb, '{"xp":500,"credits":130}'::jsonb, false, 11),
  ('mission-ai-the-transformer-12', 'world-ai-the-transformer', 'campaign-ai-the-transformer', 'operation-ai-the-transformer-2', 'attention-chamber', 'Attention Chamber', 'Every piece assembled at once, run by hand on Echo''s own recurring question -- the full self-attention computation, proven with real numbers.', 'boss', ARRAY['maya','elena','byte'], '{"requiredMissionIds":["mission-ai-the-transformer-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"attention-chamber-boss-sim"}'::jsonb, '{"xp":1200,"credits":260,"badgeIds":["attention-chamber"],"skillXp":{"transformers":55,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-the-transformer-01', 1, 'maya', 'Every technique this Arc produced got bolted onto older architectures one piece at a time -- sequence models first, then attention added on, then embeddings layered in afterward. That stops today.'),
  ('mission-ai-the-transformer-01', 2, 'elena', 'Every piece Cipher Division has assembled -- sequences, attention, embeddings -- has been bolted together, not built from one unified design. I want to build the real thing, from Echo''s own words outward, one attention head at a time.'),
  ('mission-ai-the-transformer-01', 3, 'elena', 'Start from the smallest real unit, the way we always do. Not a diagram from a paper -- one actual self-attention computation, run on four real words: Echo''s own recurring question, the one that keeps surfacing across every log this Arc has pulled.'),
  ('mission-ai-the-transformer-01', 4, 'maya', 'One computation first. Then we find out whether it was worth building from scratch.'),

  ('mission-ai-the-transformer-02', 1, 'elena', 'Self-attention answers one question for every word: given the rest of the sentence, how should this word''s representation change?'),
  ('mission-ai-the-transformer-02', 2, 'byte', 'Not a fixed embedding anymore. A representation built by looking at every other word in the same sequence and deciding how much each one matters.'),
  ('mission-ai-the-transformer-02', 3, 'elena', 'Every word does this at once, in parallel -- exactly what the step-by-step models from earlier this Arc could never pull off.'),

  ('mission-ai-the-transformer-03', 1, 'elena', 'Every word gets three learned projections of itself before attention even starts. The first is the query: what this word is looking for in the rest of the sequence.'),
  ('mission-ai-the-transformer-03', 2, 'byte', 'Take ARCHITECT, the last word in Echo''s recurring question. Its query vector is not the raw word -- it is a projection built specifically to search.'),
  ('mission-ai-the-transformer-03', 3, 'elena', 'Give ARCHITECT a simple two-number query for this example: Q_ARCHITECT = (2, 1). That vector is about to be compared against every other word in the sentence.'),

  ('mission-ai-the-transformer-04', 1, 'elena', 'If a query is what a word is looking for, a key is what a word offers up to be matched against. Every word in the sequence gets its own key vector too.'),
  ('mission-ai-the-transformer-04', 2, 'byte', 'Four keys for WHERE IS THE ARCHITECT: K_WHERE = (1, 0), K_IS = (0, 1), K_THE = (1, 1), K_ARCHITECT = (2, 1).'),
  ('mission-ai-the-transformer-04', 3, 'elena', 'A strong match between ARCHITECT''s query and another word''s key means that word matters to ARCHITECT''s new representation. A weak match means it barely registers.'),

  ('mission-ai-the-transformer-05', 1, 'elena', 'Queries and keys only decide how much attention to pay. They never get combined into the output themselves. That job belongs to a third vector: the value.'),
  ('mission-ai-the-transformer-05', 2, 'byte', 'Same four words, same recurring question. Values: V_WHERE = (1, 0), V_IS = (0, 1), V_THE = (1, 1), V_ARCHITECT = (2, 1). Once we know how much attention ARCHITECT pays to each word, we blend their value vectors, not their keys.'),
  ('mission-ai-the-transformer-05', 3, 'elena', 'Query and key decide the weights. Value is the actual content that gets carried forward once the weights are set.'),

  ('mission-ai-the-transformer-06', 1, 'byte', 'Time to run the numbers. ARCHITECT''s query is (2, 1). I am matching it against every key in Echo''s question with a dot product.'),
  ('mission-ai-the-transformer-06', 2, 'byte', 'Q_ARCHITECT dot K_WHERE equals 2. Q_ARCHITECT dot K_IS equals 1. Q_ARCHITECT dot K_THE equals 3. Q_ARCHITECT dot K_ARCHITECT equals 5.'),
  ('mission-ai-the-transformer-06', 3, 'elena', 'Those four numbers are the raw attention scores. Higher means the query and that key point in a more similar direction -- exactly the relevance signal self-attention needs.'),
  ('mission-ai-the-transformer-06', 4, 'elena', 'Real Transformers also divide every score by the square root of the key dimension before going further, purely to keep the numbers from growing too large as vectors get bigger. The ranking here does not change.'),

  ('mission-ai-the-transformer-07', 1, 'byte', 'Four raw scores: 2, 1, 3, 5. None of them mean anything as a weight yet. They need to become a proper distribution -- positive, and summing to exactly one.'),
  ('mission-ai-the-transformer-07', 2, 'byte', 'Exponentiate every score, then divide each by the total. exp(2) is about 7.39, exp(1) is about 2.72, exp(3) is about 20.09, exp(5) is about 148.41 -- total about 178.61.'),
  ('mission-ai-the-transformer-07', 3, 'byte', 'Divide each exponentiated score by that total: WHERE gets about 0.04, IS about 0.02, THE about 0.11, ARCHITECT about 0.83.'),
  ('mission-ai-the-transformer-07', 4, 'elena', 'Those four numbers are the actual attention weights. They sum to one, none of them is negative, and the largest raw score still wins the most weight -- but every word keeps at least a sliver of influence.'),

  ('mission-ai-the-transformer-08', 1, 'elena', 'One attention computation finds one kind of relationship. Real Transformers run several of them in parallel, called heads, each with its own learned query, key and value projections.'),
  ('mission-ai-the-transformer-08', 2, 'byte', 'On Echo''s recurring question, one head might weight ARCHITECT heavily toward itself, the way we just computed. A second head, with different learned projections, could instead weight THE and IS more evenly.'),
  ('mission-ai-the-transformer-08', 3, 'elena', 'Every head sees the same four words. They just learn to ask different questions of them. Afterward, every head''s output gets concatenated and passed through one more learned projection back down to the working size.'),
  ('mission-ai-the-transformer-08', 4, 'byte', 'That is the actual point of multiple heads: no single fixed notion of relevance has to carry the whole sentence.'),

  ('mission-ai-the-transformer-09', 1, 'elena', 'Here is the gap in everything built so far: self-attention treats a sequence like a bag of words. Swap WHERE and THE around and every dot product stays exactly the same.'),
  ('mission-ai-the-transformer-09', 2, 'byte', 'But WHERE IS THE ARCHITECT and THE ARCHITECT IS WHERE do not mean the same thing. Order matters, and nothing computed so far encodes it.'),
  ('mission-ai-the-transformer-09', 3, 'elena', 'The fix is positional encoding: a vector added to each word''s embedding before attention even starts, carrying information about that word''s position in the sequence.'),
  ('mission-ai-the-transformer-09', 4, 'byte', 'It does not replace the word''s meaning, it sits on top of it -- so content and position both reach the attention computation together.'),

  ('mission-ai-the-transformer-10', 1, 'elena', 'Attention is not the whole Transformer block. After every attention step, each word''s representation passes through its own small feed-forward network.'),
  ('mission-ai-the-transformer-10', 2, 'byte', 'The same two-layer network, applied independently to every word position -- ARCHITECT''s vector goes through it, WHERE''s vector goes through it, all using the same learned weights, with no mixing between positions.'),
  ('mission-ai-the-transformer-10', 3, 'elena', 'Attention is the only place information moves between words. The feed-forward layer is where each word''s own representation gets reshaped, position by position.'),

  ('mission-ai-the-transformer-11', 1, 'elena', 'One more piece before the block is complete. After both attention and the feed-forward layer, the original input gets added back on top of the output, not replaced by it.'),
  ('mission-ai-the-transformer-11', 2, 'byte', 'The output equals the layer applied to the input, plus the input itself. It looks almost too simple to matter, but stacking a dozen or more of these blocks without it makes training deep Transformers unstable.'),
  ('mission-ai-the-transformer-11', 3, 'elena', 'It also means every layer only has to learn a refinement on top of what already worked, instead of reconstructing the whole representation from nothing at every step.'),

  ('mission-ai-the-transformer-12', 1, 'maya', 'Every piece is on the table: queries, keys, values, scores, softmax, multiple heads, position, feed-forward, residuals. Time to run every step of it, together, by hand, on Echo''s own words.'),
  ('mission-ai-the-transformer-12', 2, 'elena', 'Echo''s recurring question again -- WHERE IS THE ARCHITECT -- traced start to finish this time, not one isolated piece. I want to see, in real numbers, what self-attention actually gives us that nothing earlier this Arc could.'),
  ('mission-ai-the-transformer-12', 3, 'byte', 'I have laid out ARCHITECT''s attention scores against every word in the question, the softmax weights those scores produce, and a second computation of the same word inside a sentence Echo has already spoken: GOOD EVENING, ARCHITECT.'),
  ('mission-ai-the-transformer-12', 4, 'elena', 'Run by hand on Echo''s own recurring question, self-attention gives every word a representation that depends on every other word around it -- something none of this Arc''s earlier sequence models could actually do. Prove it, three times over.'),
  ('mission-ai-the-transformer-12', 5, 'maya', 'Understanding one attention block is not the same as knowing which full architecture to build around it. Different jobs call for different shapes of the same idea.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-the-transformer-01-o1', 'mission-ai-the-transformer-01', 1, 'Diagnose the limitation', 'Identify what earlier sequence models could not do that motivates building self-attention from scratch.'),
  ('mission-ai-the-transformer-01-o2', 'mission-ai-the-transformer-01', 2, 'Name the starting point', 'State why this Act''s worked example is built from Echo''s own words instead of a generic sentence.'),

  ('mission-ai-the-transformer-02-o1', 'mission-ai-the-transformer-02', 1, 'Define self-attention', 'State what self-attention actually computes for each word in a sequence.'),
  ('mission-ai-the-transformer-02-o2', 'mission-ai-the-transformer-02', 2, 'Spot the difference from embeddings', 'Sort statements into plain word embedding or self-attention output.'),

  ('mission-ai-the-transformer-03-o1', 'mission-ai-the-transformer-03', 1, 'Define the query', 'State what a query vector represents in self-attention.'),
  ('mission-ai-the-transformer-03-o2', 'mission-ai-the-transformer-03', 2, 'Know what comes next', 'State what a word''s query vector gets compared against once it is computed.'),

  ('mission-ai-the-transformer-04-o1', 'mission-ai-the-transformer-04', 1, 'Define the key', 'State what a key vector represents in self-attention.'),
  ('mission-ai-the-transformer-04-o2', 'mission-ai-the-transformer-04', 2, 'Sort query from key', 'Sort short descriptions into query or key.'),

  ('mission-ai-the-transformer-05-o1', 'mission-ai-the-transformer-05', 1, 'Define the value', 'State what a value vector represents in self-attention.'),
  ('mission-ai-the-transformer-05-o2', 'mission-ai-the-transformer-05', 2, 'Match the analogy', 'Match query, key and value to their library-search analogy.'),

  ('mission-ai-the-transformer-06-o1', 'mission-ai-the-transformer-06', 1, 'Find the strongest match', 'Identify the highest raw attention score computed for ARCHITECT against every word in Echo''s question.'),
  ('mission-ai-the-transformer-06-o2', 'mission-ai-the-transformer-06', 2, 'Explain the scaling step', 'State why Transformers divide raw attention scores by the square root of the key dimension.'),

  ('mission-ai-the-transformer-07-o1', 'mission-ai-the-transformer-07', 1, 'Justify softmax', 'State why softmax, specifically, is used to turn raw scores into attention weights.'),
  ('mission-ai-the-transformer-07-o2', 'mission-ai-the-transformer-07', 2, 'Confirm the weights', 'Confirm the computed attention weights form a valid softmax output.'),

  ('mission-ai-the-transformer-08-o1', 'mission-ai-the-transformer-08', 1, 'Justify multiple heads', 'State the main reason Transformers run several attention heads instead of one.'),
  ('mission-ai-the-transformer-08-o2', 'mission-ai-the-transformer-08', 2, 'Order the pipeline', 'Order the steps of multi-head attention from raw input to final output.'),

  ('mission-ai-the-transformer-09-o1', 'mission-ai-the-transformer-09', 1, 'Explain the blind spot', 'State why plain self-attention cannot tell word order apart on its own.'),
  ('mission-ai-the-transformer-09-o2', 'mission-ai-the-transformer-09', 2, 'Prove the blind spot', 'Find the evidence that shows self-attention is blind to word order without positional encoding.'),

  ('mission-ai-the-transformer-10-o1', 'mission-ai-the-transformer-10', 1, 'Define the feed-forward layer''s role', 'State what the feed-forward layer adds that self-attention alone does not provide.'),
  ('mission-ai-the-transformer-10-o2', 'mission-ai-the-transformer-10', 2, 'Sort attention from feed-forward', 'Sort short descriptions into attention or feed-forward layer.'),

  ('mission-ai-the-transformer-11-o1', 'mission-ai-the-transformer-11', 1, 'Explain residual connections', 'State the problem residual connections primarily address in deep Transformer stacks.'),
  ('mission-ai-the-transformer-11-o2', 'mission-ai-the-transformer-11', 2, 'Order the full block', 'Order the steps of one complete Transformer block from input to output.'),

  ('mission-ai-the-transformer-12-o1', 'mission-ai-the-transformer-12', 1, 'Score the attention', 'Judge which computed attention-score table for ARCHITECT is arithmetically correct.'),
  ('mission-ai-the-transformer-12-o2', 'mission-ai-the-transformer-12', 2, 'Confirm softmax normalization', 'Judge which attention-weight set is a valid softmax output.'),
  ('mission-ai-the-transformer-12-o3', 'mission-ai-the-transformer-12', 3, 'Confirm context-dependence', 'Judge which evidence proves ARCHITECT''s self-attention output actually depends on its surrounding words.'),
  ('mission-ai-the-transformer-12-o4', 'mission-ai-the-transformer-12', 4, 'State the payoff', 'Having judged the scores, the weights and the context-dependence, state what self-attention actually proved.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-the-transformer-01-o1-c1', 'mission-ai-the-transformer-01-o1', 1, 'multiple_choice', 'Identify the limitation of earlier sequence models that motivates self-attention.', '{"question":"Sequence models from earlier this Arc largely process a sentence step by step, one position at a time. What does that cost them?","options":[{"id":"a","text":"Nothing, they are already as fast and flexible as any alternative"},{"id":"b","text":"Directly relating two words that are far apart in a sequence is hard, since information has to pass through every step in between"},{"id":"c","text":"They cannot use labeled data at all"},{"id":"d","text":"They require more parameters than any other architecture"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-transformer-01-o2-c1', 'mission-ai-the-transformer-01-o2', 1, 'multiple_choice', 'State why the worked example uses Echo''s own words.', '{"question":"Why does Elena insist on building self-attention using Echo''s own recurring question instead of a generic textbook sentence?","options":[{"id":"a","text":"Generic sentences are copyrighted"},{"id":"b","text":"Working the real computation on Echo''s actual words is what earlier bolted-together methods never did end to end, and it keeps the math grounded in the actual investigation"},{"id":"c","text":"It does not matter, any four words would work identically"},{"id":"d","text":"Echo''s question is the only text Cipher Division has ever recorded"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-the-transformer-02-o1-c1', 'mission-ai-the-transformer-02-o1', 1, 'multiple_choice', 'Define what self-attention computes.', '{"question":"Self-attention is best described as...","options":[{"id":"a","text":"A mechanism letting each position in a sequence build a new representation by weighting every other position in the same sequence"},{"id":"b","text":"A way to compress a sequence into a single fixed vector"},{"id":"c","text":"A rule that only lets a word look at the word immediately before it"},{"id":"d","text":"A technique for adding more layers to an RNN"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-the-transformer-02-o2-c1', 'mission-ai-the-transformer-02-o2', 1, 'drag_and_drop', 'Sort each statement into plain word embedding or self-attention output.', '{"items":[{"id":"i1","text":"Same vector every time the word appears, regardless of context"},{"id":"i2","text":"A vector that shifts depending on which words surround it in this specific sequence"},{"id":"i3","text":"Looked up once from a fixed table"},{"id":"i4","text":"Recomputed from the whole sequence every time"}],"targets":[{"id":"t1","label":"Plain word embedding"},{"id":"t2","label":"Self-attention output"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-ai-the-transformer-03-o1-c1', 'mission-ai-the-transformer-03-o1', 1, 'multiple_choice', 'Define what a query vector represents.', '{"question":"In self-attention, a word''s query vector represents...","options":[{"id":"a","text":"The final output of the attention layer"},{"id":"b","text":"What this word is effectively asking about the rest of the sequence, used to search for relevant words"},{"id":"c","text":"The raw token embedding, unchanged"},{"id":"d","text":"The position of the word in the sentence"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-transformer-03-o2-c1', 'mission-ai-the-transformer-03-o2', 1, 'multiple_choice', 'State what a query gets compared against next.', '{"question":"Given Echo''s recurring question WHERE IS THE ARCHITECT, and the query assigned to ARCHITECT is Q_ARCHITECT = (2, 1), what does this vector get compared against next?","options":[{"id":"a","text":"Nothing, the query is the final answer"},{"id":"b","text":"The key vector belonging to every word in the sequence, including ARCHITECT itself"},{"id":"c","text":"Only the key vector of the very first word in the sequence"},{"id":"d","text":"The raw pixel values of camera footage"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-the-transformer-04-o1-c1', 'mission-ai-the-transformer-04-o1', 1, 'multiple_choice', 'Define what a key vector represents.', '{"question":"A key vector in self-attention represents...","options":[{"id":"a","text":"What a word is offering, to be compared against every query searching the sequence"},{"id":"b","text":"The final weighted output of attention"},{"id":"c","text":"A random number used only for regularization"},{"id":"d","text":"The gradient used to update parameters during training"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-the-transformer-04-o2-c1', 'mission-ai-the-transformer-04-o2', 1, 'drag_and_drop', 'Sort each short description into query or key.', '{"items":[{"id":"i1","text":"What am I looking for in the rest of the sequence?"},{"id":"i2","text":"Used to compute how strongly this word matches someone else''s query"},{"id":"i3","text":"Built specifically to search outward from this word"},{"id":"i4","text":"Built specifically to be found by other words'' searches"}],"targets":[{"id":"t1","label":"Query"},{"id":"t2","label":"Key"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-ai-the-transformer-05-o1-c1', 'mission-ai-the-transformer-05-o1', 1, 'multiple_choice', 'Define what a value vector represents.', '{"question":"In self-attention, the value vector represents...","options":[{"id":"a","text":"The actual content of a word that gets carried into the output, weighted by how much attention it received"},{"id":"b","text":"The raw attention score before softmax"},{"id":"c","text":"A count of how many times the word appears in the corpus"},{"id":"d","text":"The position index of the word in the sentence"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-the-transformer-05-o2-c1', 'mission-ai-the-transformer-05-o2', 1, 'drag_and_drop', 'Match query, key and value to their library-search analogy.', '{"items":[{"id":"i1","text":"The search terms you type into a library catalog"},{"id":"i2","text":"The label on a book''s spine that your search gets matched against"},{"id":"i3","text":"The actual contents of the book you walk away and read"}],"targets":[{"id":"t1","label":"Query"},{"id":"t2","label":"Key"},{"id":"t3","label":"Value"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),

  ('mission-ai-the-transformer-06-o1-c1', 'mission-ai-the-transformer-06-o1', 1, 'investigation', 'Identify the highest raw attention score for ARCHITECT.', '{"evidence":[{"id":"e1","label":"WHERE","detail":"Q_ARCHITECT dot K_WHERE = 2"},{"id":"e2","label":"IS","detail":"Q_ARCHITECT dot K_IS = 1"},{"id":"e3","label":"THE","detail":"Q_ARCHITECT dot K_THE = 3"},{"id":"e4","label":"ARCHITECT","detail":"Q_ARCHITECT dot K_ARCHITECT = 5"}],"question":"Which raw attention score is the highest, meaning that key is the strongest match for ARCHITECT''s query?"}'::jsonb, '{"requiredEvidenceIds":["e4"]}'::jsonb),
  ('mission-ai-the-transformer-06-o2-c1', 'mission-ai-the-transformer-06-o2', 1, 'multiple_choice', 'Explain the scaling step before softmax.', '{"question":"Why do Transformers divide raw attention scores by the square root of the key dimension before softmax?","options":[{"id":"a","text":"To make the scores negative"},{"id":"b","text":"To keep the scores from growing too large as vector dimensions increase, which would otherwise push softmax toward extremely sharp, unstable weights"},{"id":"c","text":"It is purely cosmetic and changes nothing about training"},{"id":"d","text":"To convert the scores into probabilities directly, without softmax"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-the-transformer-07-o1-c1', 'mission-ai-the-transformer-07-o1', 1, 'multiple_choice', 'Justify using softmax specifically.', '{"question":"Why use softmax instead of simply dividing each raw score by the sum of all four raw scores?","options":[{"id":"a","text":"Softmax is not actually different from plain normalization"},{"id":"b","text":"Softmax turns even negative or wildly different raw scores into positive weights that sum to one, and it exaggerates the gap between the largest and smallest scores in a smooth, differentiable way"},{"id":"c","text":"Softmax always produces exactly equal weights for every word"},{"id":"d","text":"Softmax ignores the raw scores entirely and assigns weights randomly"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-transformer-07-o2-c1', 'mission-ai-the-transformer-07-o2', 1, 'investigation', 'Confirm the computed weights are a valid softmax output.', '{"evidence":[{"id":"e1","label":"Weight set A","detail":"WHERE=0.04, IS=0.02, THE=0.11, ARCHITECT=0.83 -- sums to 1.00, all positive"},{"id":"e2","label":"Weight set B","detail":"WHERE=0.04, IS=0.02, THE=0.11, ARCHITECT=1.20 -- sums to 1.37"},{"id":"e3","label":"Weight set C","detail":"WHERE=-0.10, IS=0.30, THE=0.20, ARCHITECT=0.60 -- includes a negative weight"}],"question":"Which weight set is a valid softmax output over the four attention scores?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-the-transformer-08-o1-c1', 'mission-ai-the-transformer-08-o1', 1, 'multiple_choice', 'Justify running multiple attention heads.', '{"question":"What is the main reason Transformers use multiple attention heads instead of just one?","options":[{"id":"a","text":"It is required for the code to run at all"},{"id":"b","text":"Each head can learn to attend to a different kind of relationship between words, instead of forcing one fixed notion of relevance to cover everything"},{"id":"c","text":"More heads always means less compute"},{"id":"d","text":"Multiple heads remove the need for values entirely"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-transformer-08-o2-c1', 'mission-ai-the-transformer-08-o2', 1, 'interactive_diagram', 'Order the steps of multi-head attention.', '{"diagramId":"multi-head-attention-pipeline","hotspots":[{"id":"project","label":"Project the input into separate Q, K, V sets, one per head","explanation":"Each head gets its own learned projections of the same input."},{"id":"attend","label":"Run self-attention independently within each head","explanation":"Every head computes its own scores, softmax weights and weighted sum."},{"id":"concat","label":"Concatenate every head''s output back together","explanation":"The separate head outputs are joined back into one vector per position."},{"id":"project_out","label":"Pass the concatenated result through one more learned projection","explanation":"A final projection mixes the heads back down to the working size."}],"task":"Order the steps of multi-head attention from raw input to final output."}'::jsonb, '{"correctOrderIds":["project","attend","concat","project_out"]}'::jsonb),

  ('mission-ai-the-transformer-09-o1-c1', 'mission-ai-the-transformer-09-o1', 1, 'multiple_choice', 'Explain why plain self-attention is blind to word order.', '{"question":"Without any positional information, why is plain self-attention blind to word order?","options":[{"id":"a","text":"Because attention scores are always identical for every word pair"},{"id":"b","text":"Because attention scores depend only on each word''s query and key content, not on where that word sits in the sequence, so reordering the words leaves every score unchanged"},{"id":"c","text":"Because softmax removes position information"},{"id":"d","text":"Because values are always zero"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-transformer-09-o2-c1', 'mission-ai-the-transformer-09-o2', 1, 'investigation', 'Find the evidence proving the blind spot.', '{"evidence":[{"id":"e1","label":"Word-order test","detail":"Scrambling WHERE IS THE ARCHITECT into ARCHITECT THE IS WHERE produces identical raw attention scores under plain self-attention, despite reading as nonsense"},{"id":"e2","label":"Vocabulary size","detail":"Echo''s recurring question uses only four distinct words"},{"id":"e3","label":"Softmax total","detail":"The attention weights for the question sum to 1"}],"question":"Which evidence shows why Echo''s recurring question needs positional encoding to be understood correctly?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-the-transformer-10-o1-c1', 'mission-ai-the-transformer-10-o1', 1, 'multiple_choice', 'Define the feed-forward layer''s role.', '{"question":"What does the feed-forward layer add that self-attention alone does not provide?","options":[{"id":"a","text":"A way to mix information from other words in the sequence"},{"id":"b","text":"Additional nonlinear transformation applied independently to each word''s own representation, increasing the model''s capacity beyond a purely linear mix of values"},{"id":"c","text":"Positional information"},{"id":"d","text":"The final softmax normalization"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-transformer-10-o2-c1', 'mission-ai-the-transformer-10-o2', 1, 'drag_and_drop', 'Sort each description into attention or feed-forward layer.', '{"items":[{"id":"i1","text":"Moves information between different word positions"},{"id":"i2","text":"Applies the same transformation independently to each position, with no mixing between words"},{"id":"i3","text":"Computes how much each word should weight every other word"},{"id":"i4","text":"Adds nonlinearity to each word''s own representation after attention has already mixed context in"}],"targets":[{"id":"t1","label":"Attention"},{"id":"t2","label":"Feed-forward layer"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-ai-the-transformer-11-o1-c1', 'mission-ai-the-transformer-11-o1', 1, 'multiple_choice', 'Explain what residual connections address.', '{"question":"What problem do residual connections primarily address in deep Transformer stacks?","options":[{"id":"a","text":"They remove the need for positional encoding"},{"id":"b","text":"They let gradients and information flow more directly through many stacked layers, by adding each layer''s input back to its output instead of replacing it"},{"id":"c","text":"They make attention weights sum to one"},{"id":"d","text":"They eliminate the need for multiple heads"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-transformer-11-o2-c1', 'mission-ai-the-transformer-11-o2', 1, 'interactive_diagram', 'Order the steps of one full Transformer block.', '{"diagramId":"transformer-block-flow","hotspots":[{"id":"attention","label":"Multi-head self-attention over the input","explanation":"Every position attends to every other position across all heads."},{"id":"residual1","label":"Add the block''s original input back to the attention output","explanation":"The residual connection preserves the pre-attention representation."},{"id":"feedforward","label":"Position-wise feed-forward network","explanation":"Each position is independently reshaped by the same small network."},{"id":"residual2","label":"Add the pre-feed-forward representation back to the feed-forward output","explanation":"A second residual connection preserves what attention had already produced."}],"task":"Order the steps of one complete Transformer block from input to output."}'::jsonb, '{"correctOrderIds":["attention","residual1","feedforward","residual2"]}'::jsonb),

  ('mission-ai-the-transformer-12-o1-c1', 'mission-ai-the-transformer-12-o1', 1, 'investigation', 'Judge which attention-score table is correct.', '{"evidence":[{"id":"e1","label":"Score table A","detail":"WHERE=2, IS=1, THE=3, ARCHITECT=5, computed as Q_ARCHITECT=(2,1) dotted with each word''s key vector"},{"id":"e2","label":"Score table B","detail":"WHERE=3, IS=2, THE=4, ARCHITECT=6, every score shifted up by one from table A"},{"id":"e3","label":"Score table C","detail":"WHERE=2, IS=1, THE=3, ARCHITECT=0, ARCHITECT scored as if its key did not match its own query at all"}],"question":"Byte re-ran the dot products between Q_ARCHITECT=(2,1) and every key in WHERE IS THE ARCHITECT: K_WHERE=(1,0), K_IS=(0,1), K_THE=(1,1), K_ARCHITECT=(2,1). Which score table is arithmetically correct?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-the-transformer-12-o2-c1', 'mission-ai-the-transformer-12-o2', 1, 'investigation', 'Judge which weight set is a valid softmax output.', '{"evidence":[{"id":"e1","label":"Weight set A","detail":"WHERE=0.04, IS=0.02, THE=0.11, ARCHITECT=0.83, sums to 1.00, all positive"},{"id":"e2","label":"Weight set B","detail":"WHERE=0.04, IS=0.02, THE=0.11, ARCHITECT=1.20, sums to 1.37"},{"id":"e3","label":"Weight set C","detail":"WHERE=-0.10, IS=0.30, THE=0.20, ARCHITECT=0.60, includes a negative weight"}],"question":"Which attention-weight set for WHERE IS THE ARCHITECT is a valid softmax output?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-the-transformer-12-o3-c1', 'mission-ai-the-transformer-12-o3', 1, 'investigation', 'Judge which evidence proves context-dependence.', '{"evidence":[{"id":"e1","label":"Plain embedding of ARCHITECT","detail":"x_ARCHITECT = (2, 1) in WHERE IS THE ARCHITECT, and x_ARCHITECT = (2, 1) again in GOOD EVENING, ARCHITECT -- identical every time, regardless of context"},{"id":"e2","label":"Self-attention output in WHERE IS THE ARCHITECT","detail":"z_ARCHITECT is approximately (1.81, 0.96), blended from all four words'' values weighted by that sentence''s softmax scores"},{"id":"e3","label":"Self-attention output in GOOD EVENING, ARCHITECT","detail":"z_ARCHITECT is approximately (1.68, 1.29), blended from that sentence''s three words'' values weighted by their own softmax scores"}],"question":"Which evidence proves that self-attention, unlike a plain word embedding, gives ARCHITECT a genuinely context-dependent representation?"}'::jsonb, '{"requiredEvidenceIds":["e2","e3"]}'::jsonb),
  ('mission-ai-the-transformer-12-o4-c1', 'mission-ai-the-transformer-12-o4', 1, 'boss_encounter', 'Having judged the scores, the weights and the context-dependence, state what self-attention actually proved.', '{"stages":[{"objectiveRef":"mission-ai-the-transformer-12-o1","label":"Score the attention"},{"objectiveRef":"mission-ai-the-transformer-12-o2","label":"Confirm softmax normalization"},{"objectiveRef":"mission-ai-the-transformer-12-o3","label":"Confirm context-dependence"}],"task":"Having confirmed the scores, the softmax weights, and the fact that ARCHITECT''s representation shifts between sentences, state the conclusion self-attention just proved."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-the-transformer-12-o1","mission-ai-the-transformer-12-o2","mission-ai-the-transformer-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-the-transformer-01-o1-c1', 'orientation', 'Think about how many steps it takes a step-by-step model to relate two words that are far apart in a sentence.', 10, 1),
  ('mission-ai-the-transformer-01-o1-c1', 'concept', 'If relating distant words requires passing information through every step in between, direct long-range connections are hard to learn.', 20, 2),
  ('mission-ai-the-transformer-01-o1-c1', 'solution', 'Relating far-apart words directly is hard for step-by-step models, since information has to travel through every position in between -- that is exactly the gap self-attention closes.', 30, 3),

  ('mission-ai-the-transformer-01-o2-c1', 'orientation', 'The point is not the specific words, it is what running the full computation on real data proves.', 10, 1),
  ('mission-ai-the-transformer-01-o2-c1', 'solution', 'Working the real computation on Echo''s actual words is what earlier bolted-together methods never did end to end, and it keeps the math grounded in the actual investigation.', 20, 2),

  ('mission-ai-the-transformer-02-o1-c1', 'orientation', 'Self-attention changes a word''s representation using something other than that word alone.', 10, 1),
  ('mission-ai-the-transformer-02-o1-c1', 'solution', 'Self-attention lets each position build a new representation by weighting every other position in the same sequence.', 20, 2),

  ('mission-ai-the-transformer-02-o2-c1', 'orientation', 'Ask whether the vector can change if the surrounding words change.', 10, 1),
  ('mission-ai-the-transformer-02-o2-c1', 'concept', 'A plain embedding is looked up once from a fixed table. A self-attention output is recomputed from the whole sequence every time.', 20, 2),
  ('mission-ai-the-transformer-02-o2-c1', 'solution', 'Fixed, looked-up-once vectors belong to plain embeddings. Vectors that shift with context and get recomputed from the whole sequence belong to self-attention output.', 30, 3),

  ('mission-ai-the-transformer-03-o1-c1', 'orientation', 'A query is about searching, not about storing.', 10, 1),
  ('mission-ai-the-transformer-03-o1-c1', 'solution', 'A query vector represents what this word is effectively asking about the rest of the sequence, used to search for relevant words.', 20, 2),

  ('mission-ai-the-transformer-03-o2-c1', 'orientation', 'The query alone cannot produce a weight. It needs something to compare against.', 10, 1),
  ('mission-ai-the-transformer-03-o2-c1', 'solution', 'The query gets compared against the key vector belonging to every word in the sequence, including the word itself.', 20, 2),

  ('mission-ai-the-transformer-04-o1-c1', 'orientation', 'A key is what gets offered up, not what goes searching.', 10, 1),
  ('mission-ai-the-transformer-04-o1-c1', 'solution', 'A key vector represents what a word is offering, to be compared against every query searching the sequence.', 20, 2),

  ('mission-ai-the-transformer-04-o2-c1', 'orientation', 'Ask whether each phrase describes searching outward or being found.', 10, 1),
  ('mission-ai-the-transformer-04-o2-c1', 'solution', 'Searching outward is a query. Being matched against is a key.', 20, 2),

  ('mission-ai-the-transformer-05-o1-c1', 'orientation', 'The value is what actually ends up in the output, not what decides the weighting.', 10, 1),
  ('mission-ai-the-transformer-05-o1-c1', 'solution', 'A value vector represents the actual content of a word that gets carried into the output, weighted by how much attention it received.', 20, 2),

  ('mission-ai-the-transformer-05-o2-c1', 'orientation', 'Think of a library catalog: what you type in, what is printed on a spine, and what you actually read.', 10, 1),
  ('mission-ai-the-transformer-05-o2-c1', 'solution', 'Query is the search terms you type in. Key is the label on the spine your search gets matched against. Value is the actual contents of the book you walk away with.', 20, 2),

  ('mission-ai-the-transformer-06-o1-c1', 'orientation', 'Compute each dot product between Q_ARCHITECT = (2, 1) and every key, then compare.', 10, 1),
  ('mission-ai-the-transformer-06-o1-c1', 'concept', 'A word''s query dotted with its own key is a completely valid, and often large, score.', 20, 2),
  ('mission-ai-the-transformer-06-o1-c1', 'solution', 'Q_ARCHITECT dot K_ARCHITECT equals 5, higher than its score against WHERE, IS or THE -- the strongest match here happens to be the word attending to itself.', 30, 3),

  ('mission-ai-the-transformer-06-o2-c1', 'orientation', 'The concern is about the size of the numbers before softmax, not about correctness.', 10, 1),
  ('mission-ai-the-transformer-06-o2-c1', 'solution', 'Dividing by the square root of the key dimension keeps scores from growing too large as vectors get bigger, which would otherwise push softmax toward extremely sharp, unstable weights.', 20, 2),

  ('mission-ai-the-transformer-07-o1-c1', 'orientation', 'Plain division by the sum only works cleanly if every score is already positive.', 10, 1),
  ('mission-ai-the-transformer-07-o1-c1', 'concept', 'Softmax exponentiates first, which forces every value positive and exaggerates the gap between large and small scores smoothly.', 20, 2),
  ('mission-ai-the-transformer-07-o1-c1', 'solution', 'Softmax turns even negative or wildly different raw scores into positive weights that sum to one, and it exaggerates the gap between the largest and smallest scores in a smooth, differentiable way.', 30, 3),

  ('mission-ai-the-transformer-07-o2-c1', 'orientation', 'A valid softmax output has two properties: every weight is non-negative, and they all add up to one.', 10, 1),
  ('mission-ai-the-transformer-07-o2-c1', 'solution', '0.04 + 0.02 + 0.11 + 0.83 equals 1.00, and every value is positive -- that is a valid softmax output.', 20, 2),

  ('mission-ai-the-transformer-08-o1-c1', 'orientation', 'Ask what a single, fixed notion of relevance would miss.', 10, 1),
  ('mission-ai-the-transformer-08-o1-c1', 'solution', 'Each head can learn to attend to a different kind of relationship between words, instead of forcing one fixed notion of relevance to cover everything.', 20, 2),

  ('mission-ai-the-transformer-08-o2-c1', 'orientation', 'Attention has to happen separately inside each head before anything can be combined.', 10, 1),
  ('mission-ai-the-transformer-08-o2-c1', 'concept', 'Combining head outputs only makes sense after every head has finished its own attention computation.', 20, 2),
  ('mission-ai-the-transformer-08-o2-c1', 'solution', 'Project into separate Q, K, V sets per head, run attention independently within each head, concatenate every head''s output, then pass the result through one more learned projection.', 30, 3),

  ('mission-ai-the-transformer-09-o1-c1', 'orientation', 'Ask what a dot product between a query and a key actually depends on.', 10, 1),
  ('mission-ai-the-transformer-09-o1-c1', 'concept', 'Dot products depend only on the vectors'' values, and nothing about where those vectors sit in the sequence.', 20, 2),
  ('mission-ai-the-transformer-09-o1-c1', 'solution', 'Attention scores depend only on each word''s query and key content, not on where that word sits in the sequence, so reordering the words leaves every score unchanged.', 30, 3),

  ('mission-ai-the-transformer-09-o2-c1', 'orientation', 'Look for evidence that directly shows scrambled word order producing identical scores.', 10, 1),
  ('mission-ai-the-transformer-09-o2-c1', 'solution', 'Scrambling WHERE IS THE ARCHITECT into ARCHITECT THE IS WHERE produces identical raw attention scores under plain self-attention, despite reading as nonsense -- proof that order never entered the computation.', 20, 2),

  ('mission-ai-the-transformer-10-o1-c1', 'orientation', 'The feed-forward layer never looks at any other word''s vector.', 10, 1),
  ('mission-ai-the-transformer-10-o1-c1', 'solution', 'It adds nonlinear transformation applied independently to each word''s own representation, increasing the model''s capacity beyond a purely linear mix of values.', 20, 2),

  ('mission-ai-the-transformer-10-o2-c1', 'orientation', 'Ask whether the operation mixes information between words, or stays within one word''s own vector.', 10, 1),
  ('mission-ai-the-transformer-10-o2-c1', 'solution', 'Attention moves information between positions and weights every word against every other. The feed-forward layer applies the same transformation independently to each position, with no mixing between words.', 20, 2),

  ('mission-ai-the-transformer-11-o1-c1', 'orientation', 'The concern is about how far a signal has to travel through a deep stack of layers.', 10, 1),
  ('mission-ai-the-transformer-11-o1-c1', 'concept', 'Adding a layer''s input back to its output gives gradients a direct path back through every layer, instead of only the layer''s own transformation.', 20, 2),
  ('mission-ai-the-transformer-11-o1-c1', 'solution', 'Residual connections let gradients and information flow more directly through many stacked layers, by adding each layer''s input back to its output instead of replacing it.', 30, 3),

  ('mission-ai-the-transformer-11-o2-c1', 'orientation', 'Attention comes first, and a residual add follows every sublayer, not just the last one.', 10, 1),
  ('mission-ai-the-transformer-11-o2-c1', 'solution', 'Multi-head self-attention over the input, add the block''s original input back to the attention output, run the position-wise feed-forward network, then add the pre-feed-forward representation back to the feed-forward output.', 30, 2),

  ('mission-ai-the-transformer-12-o1-c1', 'orientation', 'Recompute the dot products yourself: Q_ARCHITECT = (2, 1) against each key.', 10, 1),
  ('mission-ai-the-transformer-12-o1-c1', 'solution', 'WHERE=2, IS=1, THE=3, ARCHITECT=5 is the only table that matches Q_ARCHITECT = (2, 1) dotted against K_WHERE = (1, 0), K_IS = (0, 1), K_THE = (1, 1), K_ARCHITECT = (2, 1).', 20, 2),

  ('mission-ai-the-transformer-12-o2-c1', 'orientation', 'Check two things: does every weight stay positive, and do they sum to one.', 10, 1),
  ('mission-ai-the-transformer-12-o2-c1', 'solution', 'WHERE=0.04, IS=0.02, THE=0.11, ARCHITECT=0.83 sums to 1.00 with no negative values -- the only valid softmax output of the three.', 20, 2),

  ('mission-ai-the-transformer-12-o3-c1', 'orientation', 'The plain embedding is the one number that never changes between the evidence entries.', 10, 1),
  ('mission-ai-the-transformer-12-o3-c1', 'concept', 'Compare ARCHITECT''s self-attention output across both sentences, not against the plain embedding alone.', 20, 2),
  ('mission-ai-the-transformer-12-o3-c1', 'solution', 'The plain embedding of ARCHITECT stays fixed at (2, 1) in both sentences, but the self-attention output shifts from about (1.81, 0.96) in WHERE IS THE ARCHITECT to about (1.68, 1.29) in GOOD EVENING, ARCHITECT -- proof the representation genuinely depends on context.', 30, 3),

  ('mission-ai-the-transformer-12-o4-c1', 'orientation', 'Look at what all three judgments proved together, not as separate answers.', 15, 1),
  ('mission-ai-the-transformer-12-o4-c1', 'solution', 'Run by hand on Echo''s own recurring question, self-attention gives every word a representation that depends on every other word around it -- something none of this Arc''s earlier sequence models could actually do.', 25, 2);
